import { getGeneration } from './dex';
import germanSpeciesNames from './i18n/data/species.de.json';
import { toID } from './i18n/id';

// German → English Pokémon name mapping for importing German-language Pokémon data (spreadsheets, team lists).
//
// Server-only (imports @pkmn/data through ./dex). The map is DERIVED, not hand-written:
//   1. every official German species name from the generated dictionary `./i18n/data/species.de.json`
//      (PokeAPI, regenerated by scripts/pkmn-i18n/generate.mjs) → its English @pkmn species name;
//   2. plus SPELLING_ALIASES: hand-reviewed community spellings that are not official German display names
//      ("H-Admurai", "Wolwerock-N", "P-Tauros Aqua", …).
// translatePokemonName() throws on an unknown name and on a target @pkmn/data does not know;
// validateAllTranslations() lists every target that does not resolve (its test requires none).

/**
 * Hand-reviewed community spellings → English @pkmn name. "Marrikeck" is intentionally absent: it is not a German
 * name and no species can be verified for it, so an import containing it must fail loudly.
 */
const SPELLING_ALIASES: Readonly<Record<string, string>> = {
  'Amigento mit all Discs': 'Silvally',
  'Amigento ohne Disc': 'Silvally',
  'Arktillas': 'Avalugg',
  'H-Arktillas': 'Avalugg-Hisui',
  'Boreos-I': 'Tornadus',
  'Boreos-T': 'Tornadus-Therian',
  'Voltolos-T': 'Thundurus-Therian',
  'Demeteros-I': 'Landorus',
  'Demeteros-T': 'Landorus-Therian',
  'Cupidos-I': 'Enamorus',
  'Cupidos-T': 'Enamorus-Therian',
  'Choreogel-PomPom': 'Oricorio-Pom-Pom',
  'Deoxys-A': 'Deoxys-Attack',
  'Despotar-Mega': 'Tyranitar-Mega',
  'Metagross-Mega': 'Metagross-Mega',
  'Geowaz-Alola': 'Golem-Alola',
  'Gierspenst-Truhe': 'Gimmighoul',
  'Gierspenst-Wander': 'Gimmighoul-Roaming',
  'H-Admurai': 'Samurott-Hisui',
  'H-Dressella': 'Lilligant-Hisui',
  'H-Silvarro': 'Decidueye-Hisui',
  'H-Tornupto': 'Typhlosion-Hisui',
  'H-Washakwil': 'Braviary-Hisui',
  'Hoopa-U': 'Hoopa-Unbound',
  'Klikkdiklak': 'Klinklang',
  'Roihornior': 'Rhyperior',
  'Kyurem-Black': 'Kyurem-Black',
  'P-Tauros Aqua': 'Tauros-Paldea-Aqua',
  'P-Tauros Flare': 'Tauros-Paldea-Blaze',
  'P-Tauros Gefechtvariante': 'Tauros-Paldea-Combat',
  'Quajutsu-Ash': 'Greninja-Ash',
  'Rotom-Fan': 'Rotom-Fan',
  'Rotom-Heat': 'Rotom-Heat',
  'Rotom-Mow': 'Rotom-Mow',
  'Rotom-Wash': 'Rotom-Wash',
  'Salmagnis-F': 'Basculegion-F',
  'Salmagnis-M': 'Basculegion',
  'Servol-M': 'Indeedee',
  'Ursaluna-Blutmond': 'Ursaluna-Bloodmoon',
  'Wolwerock-N': 'Lycanroc-Midnight',
  'Wolwerock-T': 'Lycanroc', // Tagform = Midday Form
  'Wolwerock-Z': 'Lycanroc-Dusk', // Zwielichtform = Dusk Form
  'Wulaosu-Fokus': 'Urshifu',
  'Zygarde 50%': 'Zygarde',
};

const NATDEX_MAX_GEN = 9;

/**
 * The @pkmn species for a name or id, newest generation first, so National Dex–only species (Megas, Silvally,
 * Zygarde, …) resolve too. Undefined when no generation knows it (e.g. Gigantamax and Totem formes).
 */
function resolveSpecies(nameOrId: string) {
  for (let gen = NATDEX_MAX_GEN; gen >= 1; gen--) {
    const species = getGeneration(gen).species.get(nameOrId);
    if (species) return species;
  }
  return undefined;
}

function buildGermanToEnglish(): Record<string, string> {
  const map: Record<string, string> = {};
  for (const [id, german] of Object.entries(germanSpeciesNames as Readonly<Record<string, string>>)) {
    const english = resolveSpecies(id)?.name;
    if (english && !(german in map)) map[german] = english;
  }
  for (const [alias, english] of Object.entries(SPELLING_ALIASES)) {
    if (!(alias in map)) map[alias] = english;
  }
  return map;
}

/** German (official name or reviewed spelling alias) → English @pkmn species name. Built at module load. */
export const GERMAN_TO_ENGLISH: Record<string, string> = buildGermanToEnglish();

/** The same table keyed by `toID(german)`, for spellings that differ only in case, spaces or punctuation. */
const FOLDED_GERMAN_TO_ENGLISH: ReadonlyMap<string, string> = (() => {
  const folded = new Map<string, string>();
  for (const [german, english] of Object.entries(GERMAN_TO_ENGLISH)) {
    const key = toID(german);
    if (key && !folded.has(key)) folded.set(key, english);
  }
  return folded;
})();

/**
 * Translate a German Pokémon name to its English @pkmn/data canonical form.
 * Resolves an exact key first, then a `toID` fold ("wulaosu-fließend" → "Wulaosu (Fließend)").
 * Throws if the name is unknown or the English translation is invalid.
 */
export function translatePokemonName(germanName: string): string {
  const english =
    (Object.prototype.hasOwnProperty.call(GERMAN_TO_ENGLISH, germanName) ? GERMAN_TO_ENGLISH[germanName] : undefined) ??
    FOLDED_GERMAN_TO_ENGLISH.get(toID(germanName));
  if (!english) {
    throw new Error(
      `Unknown German Pokémon name: "${germanName}". Add it to SPELLING_ALIASES in german-names.ts`
    );
  }
  // Validate against @pkmn/data
  const species = resolveSpecies(english);
  if (!species) {
    throw new Error(
      `Translated name "${english}" (from "${germanName}") not found in @pkmn/data`
    );
  }
  return species.name; // canonical capitalization
}

/**
 * Validate every entry in the GERMAN_TO_ENGLISH map against @pkmn/data.
 * Returns arrays of valid and invalid translations for diagnostics.
 */
export function validateAllTranslations(): { valid: string[]; invalid: string[] } {
  const valid: string[] = [];
  const invalid: string[] = [];
  for (const [german, english] of Object.entries(GERMAN_TO_ENGLISH)) {
    const species = resolveSpecies(english);
    if (species) {
      valid.push(`${german} → ${species.name}`);
    } else {
      invalid.push(`${german} → ${english} (NOT FOUND)`);
    }
  }
  return { valid, invalid };
}
